package com.lifeos.projects;import com.lifeos.projects.dto.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/projects")public class ProjectController{private final ProjectService s;public ProjectController(ProjectService s){this.s=s;}@GetMapping public List<ProjectResponse>list(@AuthenticationPrincipal UserDetails p){return s.list(p.getUsername());}@GetMapping("/{id}")public ProjectResponse get(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){return s.get(id,p.getUsername());}@PostMapping@ResponseStatus(HttpStatus.CREATED)public ProjectResponse create(@Valid@RequestBody ProjectRequest r,@AuthenticationPrincipal UserDetails p){return s.create(r,p.getUsername());}@PutMapping("/{id}")public ProjectResponse update(@PathVariable Long id,@Valid@RequestBody ProjectRequest r,@AuthenticationPrincipal UserDetails p){return s.update(id,r,p.getUsername());}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){s.delete(id,p.getUsername());}}
